"use client"

import React, { useState, useEffect } from 'react'
import Link from 'next/link'
import { useRouter } from 'next/navigation'
import { cn } from '@/lib/utils'

export default function Navbar() {
  const [scrolled, setScrolled] = useState(false)
  const router = useRouter()

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 80)
    }
    window.addEventListener('scroll', handleScroll)
    return () => window.removeEventListener('scroll', handleScroll)
  }, [])

  return (
    <nav className={cn(
      "fixed left-1/2 -translate-x-1/2 z-[100] transition-all duration-500 flex items-center justify-between bg-white/90 backdrop-blur-md border border-stone-200 shadow-sm",
      scrolled 
        ? "w-[90%] max-w-4xl top-4 rounded-full py-3 px-6" 
        : "w-full max-w-6xl top-8 rounded-2xl py-4 px-8"
    )}>
      <div className="flex items-center gap-2">
        <div className="w-8 h-8 bg-green-600 rounded-lg flex items-center justify-center font-display font-bold text-white text-xl">
          T
        </div>
        <span className="font-display font-bold text-stone-900 text-xl tracking-tight">TaniSmart</span>
      </div>

      <div className="hidden md:flex items-center gap-8">
        <Link href="/" className="text-sm font-medium text-stone-600 hover:text-green-600 transition-colors">Beranda</Link>
        <Link href="/dashboard" className="text-sm font-medium text-stone-600 hover:text-green-600 transition-colors">Dashboard</Link>
        <Link href="/camera" className="text-sm font-medium text-stone-600 hover:text-green-600 transition-colors">Kamera</Link>
      </div>

      <button 
        onClick={() => router.push('/login')}
        className="bg-green-600 hover:bg-green-700 text-white text-sm font-bold px-6 py-2 rounded-full transition-all"
      >
        Masuk
      </button>
    </nav>
  )
}